<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class VisitorAppointmentService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function siteAccess(mixed $id,bool $client):array {$site=$this->access->requireSite($id);if($client&&!$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND user_id=:actor AND client_id=:client',['company'=>$this->company(),'actor'=>$this->actor(),'client'=>$site['client_id']]))throw HttpException::notFound();return $site;}
    private function appointment(string $id,bool $client):array {$r=$this->row('visitor_appointments','appointment_id',$id);$s=$this->siteAccess($r['site_id'],$client);if((string)$s['client_id']!==(string)$r['client_id'])throw HttpException::notFound();return $r;}
    public function list(array $input,bool $client=false):array {$this->fields($input,['site_id']);$site=$this->siteAccess($input['site_id']??null,$client);$rows=$this->db->fetchAll('SELECT appointment_id,site_id,visitor_name,purpose,arrival_from,departure_due,state,revision,approved_at,checked_in_at,checked_out_at FROM visitor_appointments WHERE company_id=:company AND site_id=:site AND client_id=:client ORDER BY appointment_id DESC LIMIT 300',['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id']]);foreach($rows as&$r)$r['overdue_checkout']=$r['state']==='CHECKED_IN'&&$r['departure_due']<gmdate('Y-m-d H:i:s');unset($r);return $rows;}
    public function create(array $input,bool $client=false):array {return $this->atomic(function()use($input,$client){$this->fields($input,['site_id','visitor_name','purpose','arrival_from','departure_due']);$site=$this->siteAccess($input['site_id']??null,$client);$from=$this->at($input['arrival_from']??null);$due=$this->at($input['departure_due']??null);if($due<=$from||$due<=gmdate('Y-m-d H:i:s')||strtotime($due.' UTC')-strtotime($from.' UTC')>7*86400||strtotime($from.' UTC')>time()+180*86400)throw HttpException::unprocessable('Choose a future visit lasting up to seven days, within the next 180 days.');$this->db->execute('INSERT INTO visitor_appointments(company_id,site_id,client_id,visitor_name,purpose,arrival_from,departure_due,created_by_user_id) VALUES(:company,:site,:client,:name,:purpose,:from,:due,:actor)',['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id'],'name'=>$this->text($input['visitor_name']??null,150),'purpose'=>$this->text($input['purpose']??null,500),'from'=>$from,'due'=>$due,'actor'=>$this->actor()]);return $this->created('visitor_appointment');});}
    public function approve(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$r=$this->appointment($id,true);if($r['state']!=='PENDING'||$r['departure_due']<=gmdate('Y-m-d H:i:s')||$this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Visit changed or expired.');$pass='svp_'.bin2hex(random_bytes(32));$this->db->execute("UPDATE visitor_appointments SET state='APPROVED',revision=revision+1,pass_hash=:hash,approved_by_user_id=:actor,approved_at=:now WHERE company_id=:company AND appointment_id=:id",['hash'=>hash('sha256',$pass),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('visitor_appointment','client_approved',$id);return ['pass'=>$pass,'note'=>'Save or print this pass now. It is shown once and is valid for one check-in during the approved window. Gate staff must verify identity.'];});}
    public function checkIn(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','pass','identity_checked']);$site=$this->siteAccess($input['site_id']??null,false);if(($input['identity_checked']??null)!==true||!is_string($input['pass']??null)||strlen($input['pass'])!==68||!str_starts_with($input['pass'],'svp_'))throw HttpException::unprocessable('Scan a valid pass and confirm the visitor identity check.');$r=$this->db->fetch('SELECT * FROM visitor_appointments WHERE company_id=:company AND site_id=:site AND client_id=:client AND pass_hash=:hash',['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id'],'hash'=>hash('sha256',$input['pass'])])??throw HttpException::notFound('Pass not found for this site.');$now=gmdate('Y-m-d H:i:s');if($r['state']!=='APPROVED'||$r['arrival_from']>$now||$r['departure_due']<=$now)throw HttpException::conflict('Pass is not yet valid, expired, cancelled or already used.');$this->gate($r,'ENTRY');$this->db->execute("UPDATE visitor_appointments SET state='CHECKED_IN',revision=revision+1,checked_in_at=:now WHERE company_id=:company AND appointment_id=:id",['now'=>$now,'company'=>$this->company(),'id'=>$r['appointment_id']]);$this->audit->record('visitor_appointment','identity_checked_in',(string)$r['appointment_id']);return ['checked_in'=>true,'appointment_id'=>(string)$r['appointment_id'],'visitor_name'=>$r['visitor_name']];});}
    private function gate(array $r,string $direction):void {$uuid=uuid4();$this->db->execute('INSERT INTO gate_register(company_id,operation_uuid,request_hash,site_id,visitor_name,purpose,direction,authorization,occurred_at,received_at,recorded_by_user_id) VALUES(:company,:uuid,:hash,:site,:name,:purpose,:direction,:auth,:now,:received,:actor)',['company'=>$this->company(),'uuid'=>$uuid,'hash'=>hash('sha256',$uuid),'site'=>$r['site_id'],'name'=>$r['visitor_name'],'purpose'=>$r['purpose'],'direction'=>$direction,'auth'=>'APPROVED','now'=>gmdate('Y-m-d H:i:s'),'received'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor()]);}
    public function transition(string $id,string $action,array $input,bool $client=false):array {return $this->atomic(function()use($id,$action,$input,$client){$this->fields($input,['expected_revision']);$r=$this->appointment($id,$client);if($this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Visit changed.');if($action==='checkout'&&!$client&&$r['state']==='CHECKED_IN'){$this->gate($r,'EXIT');$state='CHECKED_OUT';}elseif($action==='cancel'&&in_array($r['state'],['PENDING','APPROVED'],true))$state='CANCELLED';else throw HttpException::conflict('This visit action is unavailable.');$this->db->execute('UPDATE visitor_appointments SET state=:state,revision=revision+1,checked_out_at=:out WHERE company_id=:company AND appointment_id=:id',['state'=>$state,'out'=>$state==='CHECKED_OUT'?gmdate('Y-m-d H:i:s'):null,'company'=>$this->company(),'id'=>$id]);$this->audit->record('visitor_appointment',$action,$id);return ['state'=>$state];});}
}
